   q=subprocess.run([str(bin),'-c','import importlib.metadata as m;print(len(list(m.distributions())))'],capture_output=True,text=True,timeout=16)
   if q.returncode==0 and q.stdout.strip().isdigit():info['installed_python_distributions']=int(q.stdout.strip())
 venvs[key]=info
