for key,path in {'Codex':'/srv/projects/Codex/node_modules','FADEGO_package_store':'/srv/projects/fadego/.local/share/pnpm','Ferrari_private_npm':'/srv/projects/skill-universal/.runtime/npm'}.items():
 p=Path(path)
 info={'present':p.is_dir(),'path':path}
 if p.is_dir():info['top_level_directories']=len([x for x in p.iterdir() if x.is_dir() and not x.is_symlink()])
